# Break My Fix finding 1, generated by Tracefix: DualBoundary.set_good_ind returns a wrong value.
# Property (issue): All paired EAB indices are valid indices into the EAB data
# Quote: a 'pair' was established with a good OCB and an EAB index outside of the data range
# Run it with pytest: it fails for as long as the code breaks this property.

import datetime

from ocbpy._boundary import DualBoundary


def test_break_my_fix_1() -> None:
    self_after = DualBoundary(stime=datetime.datetime(2002, 10, 30), etime=datetime.datetime(2002, 11, 1), hemisphere=1)
    # The property applies to this input: self.ocb.dtime is not None and self.eab.dtime is not None
    result = self_after.set_good_ind()
    assert (all(0 <= int(e) < self_after.eab.records for e in self_after.eab_ind))
